begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id) values ('71000000-0000-0000-0000-000000000001'),('71000000-0000-0000-0000-000000000002');
insert into public.journal_entries(id,user_id,title,body) values ('72000000-0000-0000-0000-000000000001','71000000-0000-0000-0000-000000000001','Synthetic A','Private source'),('72000000-0000-0000-0000-000000000002','71000000-0000-0000-0000-000000000002','Synthetic B','Private B');
select is((select count(*) from storage.buckets where id in ('deardaily-private','deardaily-story-media') and not public),2::bigint,'both image buckets stay private');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"71000000-0000-0000-0000-000000000001","role":"authenticated"}',true);
select lives_ok($$select public.reserve_journal_media('72000000-0000-0000-0000-000000000001','73000000-0000-0000-0000-000000000001',100)$$,'A reserves an owned image');
select throws_ok($$update public.private_media set status='ready'$$,'42501',null,'ordinary client cannot bypass the trusted decoder');
select throws_ok($$select object_key from public.private_media$$,'42501',null,'object paths are hidden from the API');
select throws_ok($$insert into storage.objects(bucket_id,name) values ('deardaily-private','71000000-0000-0000-0000-000000000001/fake.webp')$$,'42501',null,'direct unsanitized Storage uploads are denied');
select throws_ok($$update public.journal_entries set writing_document='{"version":1,"content":{"type":"doc","content":[{"type":"journalImage","attrs":{"assetId":"73000000-0000-0000-0000-000000000001"}}]}}' where id='72000000-0000-0000-0000-000000000001'$$,'23514',null,'pending image cannot be attached');
reset role;
update public.private_media set status='ready',width=10,height=10 where id='73000000-0000-0000-0000-000000000001';
insert into public.story_media(id,entry_id,user_id,object_key,bytes) values ('74000000-0000-0000-0000-000000000001','72000000-0000-0000-0000-000000000001','71000000-0000-0000-0000-000000000001','74000000-0000-0000-0000-000000000001.webp',100);
select throws_ok($$insert into public.story_media(id,entry_id,user_id,object_key,bytes) select x,'72000000-0000-0000-0000-000000000001'::uuid,'71000000-0000-0000-0000-000000000001'::uuid,x::text||'.webp',5242880 from (select gen_random_uuid() x from generate_series(1,21)) q$$,'54000',null,'public copies have an independent bounded account quota');
select throws_ok($$insert into public.story_media(id,entry_id,user_id,object_key,bytes) select x,'72000000-0000-0000-0000-000000000001'::uuid,'71000000-0000-0000-0000-000000000001'::uuid,x::text||'.webp',1 from (select gen_random_uuid() x from generate_series(1,31)) q$$,'54000',null,'repeated staging cannot accumulate unlimited entry copies');
insert into deardaily_private.moderators(user_id) values ('71000000-0000-0000-0000-000000000001');
insert into public.private_media(id,entry_id,user_id,object_key,status,bytes,width,height) values ('73000000-0000-0000-0000-000000000002','72000000-0000-0000-0000-000000000002','71000000-0000-0000-0000-000000000002','71000000-0000-0000-0000-000000000002/73000000-0000-0000-0000-000000000002.webp','ready',100,10,10);
set local role authenticated;
select is((select count(*) from public.private_media where id='73000000-0000-0000-0000-000000000002'),0::bigint,'moderator A cannot read B private media metadata');
select throws_ok($$select public.reserve_journal_media('72000000-0000-0000-0000-000000000002',gen_random_uuid(),100)$$,'42501',null,'moderator A cannot reserve media for B journal');
select lives_ok($$update public.journal_entries set writing_document='{"version":1,"content":{"type":"doc","content":[{"type":"journalImage","attrs":{"assetId":"73000000-0000-0000-0000-000000000001"}}]}}' where id='72000000-0000-0000-0000-000000000001'$$,'ready owned image attaches privately');
select throws_ok($$insert into public.public_stories(id,user_id,title,body,writing_document) select id,user_id,title,body,writing_document from public.journal_entries where id='72000000-0000-0000-0000-000000000001'$$,'23514',null,'private asset identifiers cannot enter a public snapshot');
select lives_ok($$insert into public.public_stories(id,user_id,title,body,writing_document) values ('72000000-0000-0000-0000-000000000001','71000000-0000-0000-0000-000000000001','Synthetic public copy','Approved public words','{"version":1,"content":{"type":"doc","content":[{"type":"journalImage","attrs":{"publicId":"74000000-0000-0000-0000-000000000001"}}]}}')$$,'explicit public-copy identifiers publish successfully');
select set_config('request.jwt.claims','{"sub":"71000000-0000-0000-0000-000000000002","role":"authenticated"}',true);
select is((select count(*) from public.private_media where id='73000000-0000-0000-0000-000000000001'),0::bigint,'B cannot read A media metadata');
select throws_ok($$select public.reserve_journal_media('72000000-0000-0000-0000-000000000001',gen_random_uuid(),100)$$,'42501',null,'B cannot reserve media for A entry');
select throws_ok($$update public.journal_entries set writing_document='{"version":1,"content":{"type":"doc","content":[{"type":"journalImage","attrs":{"assetId":"73000000-0000-0000-0000-000000000001"}}]}}' where id='72000000-0000-0000-0000-000000000002'$$,'23514',null,'B cannot attach A private image');
select throws_ok($$insert into public.public_stories(id,user_id,title,body,writing_document) values ('72000000-0000-0000-0000-000000000002','71000000-0000-0000-0000-000000000002','Spoof','No','{"version":1,"content":{"type":"doc","content":[{"type":"journalImage","attrs":{"publicId":"74000000-0000-0000-0000-000000000001"}}]}}')$$,'23514',null,'B cannot publish A prepared public media');
set local role anon;
select set_config('request.jwt.claims','{"role":"anon"}',true);
select throws_ok($$select id from public.private_media$$,'42501',null,'anonymous private media access denied');
select is((select count(*) from public.story_media),1::bigint,'anonymous reads only referenced published media identifiers');
select throws_ok($$select object_key from public.story_media$$,'42501',null,'public media API hides Storage keys and ownership');
select ok((select writing_document::text not like '%assetId%' from public.public_stories),'public snapshot has no private media identifiers');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"71000000-0000-0000-0000-000000000001","role":"authenticated"}',true);
select lives_ok($$delete from public.public_stories where id='72000000-0000-0000-0000-000000000001'$$,'A unpublishes');
select is((select count(*) from public.private_media),1::bigint,'unpublishing preserves the private original');
select throws_ok($$select * from public.media_gc$$,'42501',null,'cleanup queue remains service-only');
set local role anon;
select set_config('request.jwt.claims','{"role":"anon"}',true);
select is((select count(*) from public.story_media),0::bigint,'unpublish revokes public media registry access');
reset role;
select is((select count(*) from public.media_gc where bucket='deardaily-story-media'),1::bigint,'unpublish queues exact public objects for cleanup');
select * from finish();
rollback;
